package vela.app.spike

import java.util.Base64

/**
 * 合成的 2 秒 MPEG-TS（160x90 H.264 Baseline + AAC）和 2 秒 AAC ADTS。
 * 由测试在运行时按分片序号平移 PCR/PTS，不访问真实站点，也不依赖 ffmpeg。
 */
internal object TsMedia {
    const val SEGMENT_TICKS: Long = 180_000L
    private const val PACKET = 188

    val videoTemplate: ByteArray = Base64.getDecoder().decode(VIDEO_B64)
    val audioTemplate: ByteArray = Base64.getDecoder().decode(AUDIO_B64)

    fun videoSegment(index: Long): ByteArray = shift(videoTemplate, index * SEGMENT_TICKS)

    fun videoParts(index: Long, parts: Int = 4): List<ByteArray> {
        val all = videoSegment(index)
        val packets = all.size / PACKET
        val base = packets / parts
        val extra = packets % parts
        val out = ArrayList<ByteArray>(parts)
        var at = 0
        for (i in 0 until parts) {
            val n = base + if (i < extra) 1 else 0
            out.add(all.copyOfRange(at * PACKET, (at + n) * PACKET))
            at += n
        }
        return out
    }

    private fun shift(src: ByteArray, add: Long): ByteArray {
        val out = src.copyOf()
        val seen = HashSet<Int>()
        var i = 0
        while (i + PACKET <= out.size) {
            if (out[i] != 0x47.toByte()) break
            val pid = ((out[i + 1].toInt() and 0x1F) shl 8) or (out[i + 2].toInt() and 0xFF)
            val pusi = out[i + 1].toInt() and 0x40 != 0
            val afc = (out[i + 3].toInt() shr 4) and 0x3
            var payload = i + 4
            if (afc == 2 || afc == 3) {
                val afl = out[i + 4].toInt() and 0xFF
                if (afl > 0) {
                    val flagsAt = i + 5
                    var flags = out[flagsAt].toInt() and 0xFF
                    if (pid != 0 && pid != 0x1FFF && pid !in seen) {
                        flags = flags or 0x80
                        out[flagsAt] = flags.toByte()
                    }
                    if (flags and 0x10 != 0 && afl >= 7) {
                        addPcr(out, i + 6, add)
                    }
                }
                payload = i + 5 + afl
            }
            if (pid != 0) seen.add(pid)
            if (pusi) shiftPes(out, payload, i + PACKET, add)
            i += PACKET
        }
        return out
    }

    private fun addPcr(b: ByteArray, o: Int, add: Long) {
        val b0 = b[o].toLong() and 0xFF
        val b1 = b[o + 1].toLong() and 0xFF
        val b2 = b[o + 2].toLong() and 0xFF
        val b3 = b[o + 3].toLong() and 0xFF
        val b4 = b[o + 4].toInt() and 0xFF
        val base = (b0 shl 25) or (b1 shl 17) or (b2 shl 9) or (b3 shl 1) or (b4 shr 7).toLong()
        val extHigh = b4 and 0x01
        val newBase = (base + add) and 0x1FFFFFFFFL
        b[o] = ((newBase shr 25) and 0xFF).toByte()
        b[o + 1] = ((newBase shr 17) and 0xFF).toByte()
        b[o + 2] = ((newBase shr 9) and 0xFF).toByte()
        b[o + 3] = ((newBase shr 1) and 0xFF).toByte()
        val low = (newBase and 1).toInt()
        b[o + 4] = ((low shl 7) or 0x7E or extHigh).toByte()
    }

    private fun shiftPes(b: ByteArray, off: Int, limit: Int, add: Long) {
        if (off + 14 > limit) return
        if (b[off].toInt() != 0 || b[off + 1].toInt() != 0 || (b[off + 2].toInt() and 0xFF) != 1) return
        val sid = b[off + 3].toInt() and 0xFF
        if (sid == 0xBE || sid == 0xBF || sid == 0xBC) return
        val flags = b[off + 7].toInt() and 0xFF
        val ptsDts = (flags shr 6) and 0x3
        if (ptsDts < 2) return
        writePts(b, off + 9, (readPts(b, off + 9) + add) and 0x1FFFFFFFFL)
        if (ptsDts == 3 && off + 19 <= limit) {
            writePts(b, off + 14, (readPts(b, off + 14) + add) and 0x1FFFFFFFFL)
        }
    }

    private fun readPts(b: ByteArray, o: Int): Long {
        val b0 = b[o].toLong() and 0xFF
        val b1 = b[o + 1].toLong() and 0xFF
        val b2 = b[o + 2].toLong() and 0xFF
        val b3 = b[o + 3].toLong() and 0xFF
        val b4 = b[o + 4].toLong() and 0xFF
        return ((b0 shr 1) and 7) shl 30 or
            (b1 shl 22) or
            ((b2 shr 1) shl 15) or
            (b3 shl 7) or
            (b4 shr 1)
    }

    private fun writePts(b: ByteArray, o: Int, value: Long) {
        val v = value and 0x1FFFFFFFFL
        val prefix = b[o].toInt() and 0xF0
        val p32 = ((v shr 30) and 7).toInt()
        b[o] = (prefix or (p32 shl 1) or 1).toByte()
        b[o + 1] = ((v shr 22) and 0xFF).toByte()
        b[o + 2] = ((((v shr 15) and 0x7F).toInt() shl 1) or 1).toByte()
        b[o + 3] = ((v shr 7) and 0xFF).toByte()
        b[o + 4] = (((v and 0x7F).toInt() shl 1) or 1).toByte()
    }

    private const val VIDEO_B64 = ""
    private const val AUDIO_B64 = ""
}
